using System;
using System.Collections;
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;

namespace AssetDependencyGrapher
{
    public static class AssetDependencyScanner
    {
        public static void StartScan(ScanSettings settings, Action<CircularDependencyGraph> onComplete)
        {
            EditorApplication.update += () =>
            {
                EditorApplication.update -= null;
                StartCoroutine(ScanCoroutine(settings, onComplete));
            };
        }

        private static IEnumerator ScanCoroutine(ScanSettings settings, Action<CircularDependencyGraph> onComplete)
        {
            string[] guids = AssetDatabase.FindAssets("t:Prefab t:Material", settings.FolderPath == null ? new[] { "Assets" } : new[] { settings.FolderPath });
            var graph = new CircularDependencyGraph();
            var visited = new HashSet<string>();
            var stack = new Stack<string>();
            var path = new List<string>();

            for (int i = 0; i < guids.Length; i++)
            {
                string guid = guids[i];
                string pathStr = AssetDatabase.GUIDToAssetPath(guid);
                EditorUtility.DisplayProgressBar("Scanning Dependencies", $"Processing {i + 1}/{guids.Length}: {pathStr}", (float)i / guids.Length);

                if (!visited.Contains(guid))
                {
                    FindCycles(guid, visited, stack, path, graph);
                }
                yield return null;
            }

            EditorUtility.ClearProgressBar();
            onComplete?.Invoke(graph);
        }

        private static void FindCycles(string currentGuid, HashSet<string> visited, Stack<string> stack, List<string> path, CircularDependencyGraph graph)
        {
            visited.Add(currentGuid);
            stack.Push(currentGuid);
            path.Add(currentGuid);

            string currentPath = AssetDatabase.GUIDToAssetPath(currentGuid);
            string[] dependencies = AssetDatabase.GetDependencies(currentGuid, true);

            foreach (string depGuid in dependencies)
            {
                if (depGuid == currentGuid)
                {
                    graph.AddCycle(new List<AssetReference> { new AssetReference(currentPath, GetAssetType(currentPath)) });
                    continue;
                }

                if (stack.Contains(depGuid))
                {
                    int startIdx = path.IndexOf(depGuid);
                    var cycle = new List<AssetReference>();
                    for (int i = startIdx; i < path.Count; i++)
                    {
                        string p = AssetDatabase.GUIDToAssetPath(path[i]);
                        cycle.Add(new AssetReference(p, GetAssetType(p)));
                    }
                    graph.AddCycle(cycle);
                }
                else if (!visited.Contains(depGuid))
                {
                    FindCycles(depGuid, visited, stack, path, graph);
                }
            }

            path.RemoveAt(path.Count - 1);
            stack.Pop();
        }

        private static string GetAssetType(string path)
        {
            var obj = AssetDatabase.LoadAssetAtPath<Object>(path);
            return obj != null ? obj.GetType().Name : "Unknown";
        }
    }
}

