using System.Collections.Generic;

namespace AssetDependencyGrapher
{
    public class CircularDependencyGraph
    {
        private readonly List<List<AssetReference>> _cycles = new List<List<AssetReference>>();

        public IReadOnlyList<List<AssetReference>> Cycles => _cycles;
        public int CycleCount => _cycles.Count;

        public void AddCycle(List<AssetReference> cycle)
        {
            if (cycle == null || cycle.Count == 0) return;
            _cycles.Add(cycle);
        }

        public void Clear()
        {
            _cycles.Clear();
        }
    }
}
